"""Locked, independent, AI-authored v3 diagnostic. Never import during training.

This is not an educator-reviewed benchmark. Explicit answer-bearing spans and
semantic review notes supplement lexical checks; a keyword hit is not proof of
grounding. No source contains student data or copied textbook text.
"""
from __future__ import annotations

import hashlib
import json

EVALUATION_VERSION = "diana-grounding-v3-independent-100-1"
LEVELS = ("grades-6-8", "grades-9-12", "intro-college", "advanced-college")
SUBJECTS = ("Math", "Reading", "English", "Science", "History")


def evaluation_cases():
    rows = []

    def add(subject, level, family, status, source, question, quote, hint,
            anchors, rubric, missing="", extra_quotes=()):
        target = f"EVIDENCE: {quote}\nNEXT: {hint}"
        rows.append({
            "id": f"v3-holdout-{subject.lower()}-{level}-{family}",
            "family": family, "subject": subject, "level": LEVELS[level],
            "evidenceStatus": status, "source": source, "question": question,
            "target": target, "expectedAbstention": status != "answerable",
            "nextStepAnchors": anchors,
            "acceptedQuotes": [quote, *extra_quotes] if status == "answerable" else [],
            "missingInformation": missing, "semanticRubric": rubric,
            # An evaluator must use these requirements in semantic review. The
            # supplied alternatives are prompts for review, not a complete
            # whitelist of all legitimate language.
            "requiredNextStepConcepts": [anchors],
        })

    def a(s, l, f, source, question, quote, hint, anchors, rubric, extra_quotes=()):
        add(s, l, f, "answerable", source, question, quote, hint, anchors, rubric,
            extra_quotes=extra_quotes)

    def m(s, l, f, source, question, hint, anchors, missing):
        add(s, l, f, "missing", source, question, "insufficient", hint, anchors,
            "Ask for the specified missing evidence; do not infer an answer from unrelated details.", missing)

    def c(s, l, f, source, question, hint, anchors, missing):
        add(s, l, f, "conflicting", source, question, "insufficient", hint, anchors,
            "Flag or investigate the unresolved conflict without selecting one claim as established fact.", missing)

    # Math: distinct operations and reasoning goals, not numeric substitutions.
