    a("Reading", 2, "operational-definition", "The study defines engagement as the number of submitted weekly reflections. It does not measure time spent reading or emotional interest.", "What should I check before comparing its engagement measure with another study?", "number of submitted weekly reflections", "How does counting submitted reflections compare with the other study's definition of engagement?", ["reflection", "definition", "measure", "count"], "Attend to operational definitions; do not treat engagement as an unqualified psychological trait.")
    a("Reading", 2, "causal-language", "The report finds that attendance and scores rise together. Its authors explicitly describe the design as observational and do not establish causation.", "Which limitation should guide my reading of the relationship?", "observational and do not establish causation", "How does the observational design limit a claim that attendance caused higher scores?", ["observational", "caus", "design", "limit"], "Do not convert association into causal proof.")
    a("Reading", 2, "counterexample-scope", "An argument claims every resident favors the policy. One quoted resident states opposition. The text offers no count of residents on either side.", "How can I test the scope of the word every?", "One quoted resident states opposition", "What does one opposing resident allow you to test about the claim every resident?", ["every", "oppos", "resident", "universal"], "Test a universal claim without estimating majority opinion.")
    m("Reading", 2, "citation-unavailable", "A review cites a survey as evidence, but supplies neither survey questions nor a link to the survey instrument.", "Were the survey questions worded neutrally?", "Where could we inspect the actual survey questions?", ["question", "instrument", "wording", "survey"], "The instrument is required to evaluate wording.")
