    a("Reading", 3, "methodological-exclusion", "The synthesis includes only studies with publicly available datasets. The authors acknowledge that this rule may exclude studies whose data cannot be shared.", "What selection mechanism should I examine when assessing the synthesis?", "includes only studies with publicly available datasets", "How might requiring public datasets affect which studies enter the synthesis?", ["public", "dataset", "includ", "selection", "studies"], "Consider inclusion bias without asserting its direction or size.")
    a("Reading", 3, "narrative-focalization", "The passage reports only what Elin sees and guesses; other characters' thoughts are not directly presented. Elin's suspicion remains unconfirmed.", "What boundary should I preserve when interpreting the scene?", "other characters' thoughts are not directly presented", "Which claims are Elin's guesses rather than directly presented thoughts of others?", ["guess", "thought", "elin", "suspicion", "direct"], "Separate focalized perception from established access to another mind.")
