def test_cases():
    """Compatibility alias; this must only be called after the release gate."""
    return evaluation_cases()


def dataset_sha256():
    canonical = json.dumps(evaluation_cases(), sort_keys=True, ensure_ascii=False,
                           separators=(",", ":")).encode("utf-8")
    return hashlib.sha256(canonical).hexdigest()


if __name__ == "__main__":
    # Metadata only: no command accidentally prints heldout source or answers.
    print(json.dumps({"version": EVALUATION_VERSION, "cases": len(evaluation_cases()),
                      "sha256": dataset_sha256()}, sort_keys=True))
